//! Faithful re-implementation of the `std::stoi` semantics the C++ parser
//! relies on when turning the `:<port>` slice of an authority into an integer.

/// `std::isspace` in the default "C" locale.
fn is_c_space(b: u8) -> bool {
    matches!(b, b' ' | b'\t' | b'\n' | 0x0b | 0x0c | b'\r')
}

/// Equivalent of `std::stoi(s)` for base 10.
///
/// Returns `None` where the C++ call would throw, i.e. `std::invalid_argument`
/// when no digits could be converted and `std::out_of_range` when the value
/// does not fit into an `int`. Like `stoi`, leading whitespace and a single
/// sign are accepted and trailing garbage is ignored (`"80abc"` -> `80`).
pub fn stoi(s: &str) -> Option<i32> {
    let bytes = s.as_bytes();
    let mut i = 0;

    while i < bytes.len() && is_c_space(bytes[i]) {
        i += 1;
    }

    let negative = match bytes.get(i) {
        Some(b'-') => {
            i += 1;
            true
        }
        Some(b'+') => {
            i += 1;
            false
        }
        _ => false,
    };

    let start = i;
    // Accumulate in i64 so that anything beyond the `int` range is detectable
    // rather than wrapping; saturating there is enough because the caller only
    // keeps values inside 0..=65535 anyway.
    let mut value: i64 = 0;
    while i < bytes.len() && bytes[i].is_ascii_digit() {
        if value <= i64::from(i32::MAX) {
            value = value * 10 + i64::from(bytes[i] - b'0');
        }
        i += 1;
    }

    if i == start {
        return None; // std::invalid_argument
    }

    let value = if negative { -value } else { value };
    if value < i64::from(i32::MIN) || value > i64::from(i32::MAX) {
        return None; // std::out_of_range
    }
    Some(value as i32)
}

/// ASCII-only lowercasing, matching `std::tolower` under the "C" locale
/// (bytes >= 0x80 are left untouched).
pub fn ascii_lowercase(s: &str) -> String {
    s.chars()
        .map(|c| if c.is_ascii() { c.to_ascii_lowercase() } else { c })
        .collect()
}

