//! The `URL` type: a byte-for-byte behavioural port of `url_parser::URL`.

use super::numeric::{ascii_lowercase, stoi};

/// Ports outside this range are rejected and reported as `NO_PORT`.
const MAX_PORT: i32 = 65535;

/// Value reported by [`URL::port`] when the URL carries no usable port.
pub const NO_PORT: i32 = -1;

/// A parsed URL.
///
/// The parse is deliberately permissive: no component is validated beyond the
/// port, and the input is split purely positionally, in this order:
///
/// 1. the first `#` splits off the fragment,
/// 2. the first `?` in what remains splits off the query,
/// 3. the first `://` in what remains splits scheme from the rest.
///
/// Without a `://` there is no authority at all and the whole remainder is the
/// path, so `example.com` parses as a bare path.
#[derive(Debug, Clone, Default, PartialEq, Eq)]
pub struct URL {
    scheme: String,
    userinfo: String,
    host: String,
    port: i32,
    path: String,
    query: String,
    fragment: String,
}

impl URL {
    /// Parses `url`, mirroring the C++ constructor.
    pub fn new(url: &str) -> Self {
        let mut parsed = URL {
            port: NO_PORT,
            ..Default::default()
        };
        parsed.parse(url);
        parsed
    }

    fn parse(&mut self, url: &str) {
        let mut rest = url;

        if let Some(hash) = rest.find('#') {
            self.fragment = rest[hash + 1..].to_string();
            rest = &rest[..hash];
        }

        if let Some(mark) = rest.find('?') {
            self.query = rest[mark + 1..].to_string();
            rest = &rest[..mark];
        }

        match rest.find("://") {
            Some(sep) => {
                self.scheme = ascii_lowercase(&rest[..sep]);
                self.parse_authority(&rest[sep + 3..]);
            }
            // No scheme separator: everything left over is the path.
            None => self.path = rest.to_string(),
        }
    }

    /// Splits `rest` (everything after `://`) into authority and path, then
    /// breaks the authority down into userinfo, host and port.
    fn parse_authority(&mut self, rest: &str) {
        let authority = match rest.find('/') {
            Some(slash) => {
                // The separating slash belongs to the path.
                self.path = rest[slash..].to_string();
                &rest[..slash]
            }
            None => rest,
        };

        // A leading `userinfo@` is split off first, so that only the trailing
        // host:port portion is scanned for the port separator. That is why
        // `a:1@b` has no port: the `:` sits inside the userinfo.
        let host_port = match authority.find('@') {
            Some(at) => {
                self.userinfo = authority[..at].to_string();
                &authority[at + 1..]
            }
            None => authority,
        };

        match host_port.find(':') {
            Some(colon) => {
                self.host = host_port[..colon].to_string();
                self.port = match stoi(&host_port[colon + 1..]) {
                    Some(port) if (0..=MAX_PORT).contains(&port) => port,
                    _ => NO_PORT,
                };
            }
            None => self.host = host_port.to_string(),
        }
    }

    /// The scheme, lowercased, without the `://`.
    pub fn scheme(&self) -> &str {
        &self.scheme
    }

    /// The credentials preceding `@`, if any.
    pub fn userinfo(&self) -> &str {
        &self.userinfo
    }

    /// The host, with neither userinfo nor port.
    pub fn host(&self) -> &str {
        &self.host
    }

    /// The port, or [`NO_PORT`] when absent or unusable.
    pub fn port(&self) -> i32 {
        self.port
    }

    /// The path, including its leading `/`.
    pub fn path(&self) -> &str {
        &self.path
    }

    /// The query, without the leading `?`.
    pub fn query(&self) -> &str {
        &self.query
    }

    /// The fragment, without the leading `#`.
    pub fn fragment(&self) -> &str {
        &self.fragment
    }

    /// The authority, rebuilt from its parts rather than echoed verbatim.
    ///
    /// Because it is reassembled, the port is normalised (`:0080` comes back as
    /// `:80`) and dropped entirely when unusable, and an empty userinfo takes
    /// its `@` with it.
    pub fn authority(&self) -> String {
        let mut authority = String::new();
        if !self.userinfo.is_empty() {
            authority.push_str(&self.userinfo);
            authority.push('@');
        }
        authority.push_str(&self.host);
        if self.port >= 0 {
            authority.push(':');
            authority.push_str(&self.port.to_string());
        }
        authority
    }

    /// Whether the URL named something: a host, or failing that a path.
    ///
    /// Note this looks at the host and not at [`authority`](Self::authority),
    /// so `http://:8080` is invalid despite reporting a non-empty authority.
    pub fn is_valid(&self) -> bool {
        !self.host.is_empty() || !self.path.is_empty()
    }
}

