        let u = URL::new("http://example.com#frag?q=1");
        assert_eq!(u.fragment(), "frag?q=1");
        assert_eq!(u.query(), "");
    }

    #[test]
    fn query_and_fragment_are_split_before_the_scheme() {
        let u = URL::new("?a://b");
        assert_eq!(u.scheme(), "");
        assert_eq!(u.query(), "a://b");
        assert!(!u.is_valid());
    }

    #[test]
    fn port_follows_stoi_semantics() {
        let port_of = |s: &str| URL::new(s).port();
        assert_eq!(port_of("http://h:0080/p"), 80); // leading zeros
        assert_eq!(port_of("http://h:80abc/p"), 80); // trailing garbage
        assert_eq!(port_of("http://h:+7/p"), 7); // explicit sign
        assert_eq!(port_of("http://h: 80/p"), 80); // leading whitespace
        assert_eq!(port_of("http://h:0/p"), 0); // zero is in range
        assert_eq!(port_of("http://h:65535/p"), 65535);
        assert_eq!(port_of("http://h:65536/p"), NO_PORT); // out of range
        assert_eq!(port_of("http://h:-5/p"), NO_PORT); // negative
        assert_eq!(port_of("http://h:/p"), NO_PORT); // no digits
        assert_eq!(port_of("http://h:abc/p"), NO_PORT);
        assert_eq!(port_of("http://h:99999999999999999999/p"), NO_PORT); // overflows int
    }

    #[test]
    fn port_colon_is_searched_after_the_userinfo() {
        // The only colon sits inside the userinfo, so there is no port.
        let u = URL::new("http://a:1@b/p");
        assert_eq!(u.port(), NO_PORT);
        assert_eq!(u.authority(), "a:1@b");
        // Only the first `@` delimits userinfo; later ones belong to the host.
        let u = URL::new("http://a@b@c:99/p");
        assert_eq!(u.userinfo(), "a");
        assert_eq!(u.host(), "b@c");
        assert_eq!(u.port(), 99);
    }

    #[test]
    fn authority_is_rebuilt_not_echoed() {
        // The port is normalised through the integer round-trip.
        assert_eq!(URL::new("http://h:0080/p").authority(), "h:80");
        // An unusable port is dropped along with its colon.
        assert_eq!(URL::new("http://h:abc/p").authority(), "h");
        // An empty userinfo takes its `@` with it.
        assert_eq!(URL::new("http://@example.com:8080/p").authority(), "example.com:8080");
        // An empty host does not.
        assert_eq!(URL::new("http://example.com@:8080/p").authority(), "example.com@:8080");
    }

    #[test]
    fn validity_tracks_host_and_path_only() {
        assert!(URL::new("http://example.com").is_valid());
        assert!(URL::new("http:///path").is_valid()); // no host, but a path
        assert!(URL::new("://example.com").is_valid()); // no scheme, but a host
        assert!(!URL::new("").is_valid());
        assert!(!URL::new("http://").is_valid());
        assert!(!URL::new("?q=1").is_valid()); // a query alone is not enough
        assert!(!URL::new("#frag").is_valid());
        // Non-empty authority, but the host itself is empty.
        let u = URL::new("http://:8080");
        assert_eq!(u.authority(), ":8080");
        assert!(!u.is_valid());
    }

    #[test]
    fn input_is_never_trimmed() {
        let u = URL::new("  http://example.com  ");
        assert_eq!(u.scheme(), "  http");
        assert_eq!(u.host(), "example.com  ");
    }
}

